// Watch Face Format (WFF) face: no code, resources only. One signed release APK per
// accent flavour, package com.nightwise.watchwise.watchfacepush.commitgrid_<accent>
// (Watch Face Push requires the "<app package>.watchfacepush." prefix).
// res/raw/watchface.xml etc. are generated by tools/gen_watchfaces.py.

plugins {
    alias(libs.plugins.android.application)
}

val accents = listOf("green", "blue", "purple", "orange")

android {
    namespace = "com.nightwise.watchwise.watchfacepush.commitgrid"
    compileSdk {
        version = release(37)
    }
    enableKotlin = false

    defaultConfig {
        // WFF version 2 needs Wear OS 5 / API 34.
        minSdk = 34
        targetSdk = 34
        versionCode = 1
        versionName = "1.0"
    }

    // Pushed watch faces must be signed with a different key than the app.
    signingConfigs {
        create("watchface") {
            storeFile = rootProject.file("watchfaces/watchface-signing.jks")
            storePassword = "watchwise"
            keyAlias = "watchface"
            keyPassword = "watchwise"
        }
    }

    flavorDimensions += "accent"
    productFlavors {
        accents.forEach { accent ->
            create(accent) {
                dimension = "accent"
                applicationId = "com.nightwise.watchwise.watchfacepush.commitgrid_$accent"
            }
        }
    }

    buildTypes {
        release {
            signingConfig = signingConfigs.getByName("watchface")
            // Strips any dex: a WFF watch face must contain resources only.
            isMinifyEnabled = true
            isShrinkResources = false
        }
    }
}
